   while Present (Comp) loop
      if Is_Type (Comp) and then Is_Itype (Comp) then
         Set_Has_Delayed_Freeze (Comp, False);
         Set_Is_Frozen (Comp);

         if Is_Access_Type (Comp) then
            Layout_Type (Comp);
         end if;

         if Is_Record_Type (Comp) or else Is_Protected_Type (Comp) then
            Undelay_Itypes (Comp);
         end if;

